<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add business | Net-Works</title><style>body{margin:0;background:#f4f7fb;color:#17233c;font-family:Inter,Arial,sans-serif}.wrap{max-width:860px;margin:40px auto;padding:0 20px}.card{background:#fff;border:1px solid #e3e9f2;border-radius:16px;padding:28px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.full{grid-column:1/-1}label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}input,select,textarea{box-sizing:border-box;width:100%;padding:11px;border:1px solid #d8e1ed;border-radius:9px;font:inherit}textarea{min-height:100px}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.btn{padding:11px 16px;border-radius:9px;border:1px solid #d8e1ed;text-decoration:none;color:#40506b;background:#fff;font-weight:700}.primary{background:#397ef6;color:#fff;border-color:#397ef6}.error{color:#b42318;font-size:12px}@media(max-width:650px){.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><main class="wrap"><h1>Add a business</h1><p>Your business will remain pending until an administrator approves it.</p>@if($errors->any())<div class="error">{{$errors->first()}}</div>@endif<form class="card" method="post" action="{{route('member.businesses.store')}}">@csrf<div class="grid"><div class="full"><label>Business name *</label><input name="business_name" value="{{old('business_name')}}" required></div><div class="full"><label>Categories *</label><select name="category_ids[]" multiple size="6" required>@foreach($categories as $category)<option value="{{$category->bcm_id}}" @selected(in_array($category->bcm_id,old('category_ids',[])))>{{$category->name}}</option>@endforeach</select></div><div><label>Business email</label><input type="email" name="business_email" value="{{old('business_email')}}"></div><div><label>Business phone</label><input name="business_phone" value="{{old('business_phone')}}"></div><div class="full"><label>Description</label><textarea name="description">{{old('description')}}</textarea></div><div class="full"><label>Address</label><input name="address1" value="{{old('address1')}}"></div><div><label>City</label><input name="city" value="{{old('city')}}"></div><div><label>PIN code</label><input name="pincode" value="{{old('pincode')}}"></div><div><label>Country</label><select name="country"><option value="">Select</option>@foreach($countries as $country)<option value="{{$country->id}}" @selected(old('country')==$country->id)>{{$country->name}}</option>@endforeach</select></div></div><div class="actions"><a class="btn" href="{{route('dashboard.index')}}">Cancel</a><button class="btn primary">Create business</button></div></form></main></body></html>
